// The share preview image for X, Slack, iMessage and the rest (served at /og/card.png).
// It lives in a Pages Function because the site's build publishes only index.html and the coffee list.
// To change it: render a new 1200x630 PNG and replace PNG below with its base64.
const PNG = "";

let bytes;
export function onRequestGet() {
  bytes = bytes || Uint8Array.from(atob(PNG), (c) => c.charCodeAt(0));
  return new Response(bytes, {
    headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" },
  });
}
